function countDistinctIntegers(nums) {
  const seen = new Set();
  for (const num of nums) {
    seen.add(num);
    let reversed = 0;
    for (let rest = num; rest > 0; rest = Math.floor(rest / 10)) {
      reversed = reversed * 10 + (rest % 10);
    }
    seen.add(reversed);
  }
  return seen.size;
}

