function countDistinctIntegers(nums) {
  const all = nums.slice();
  for (const v of nums) all.push(Number(String(v).split('').reverse().join('')));
  all.sort((a, b) => a - b);
  let distinct = 0;
  for (let i = 0; i < all.length; i++) if (i === 0 || all[i] !== all[i - 1]) distinct++;
  return distinct;
}

