function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const reverse = (v) => Number(String(v).split('').reverse().join(''));
  const n = size === 'large' ? int(1500, 2000) : int(1, 8);
  const digits = size === 'large' ? 6 : int(1, 3);
  const nums = [];
  for (let i = 0; i < n; i++) {
    const r = rand();
    let value;
    if (nums.length && r < 0.2) value = nums[int(0, nums.length - 1)];
    else if (nums.length && r < 0.4) value = reverse(nums[int(0, nums.length - 1)]);
    else if (r < 0.55) value = int(1, 99) * 10 ** int(0, digits);
    else value = int(1, 10 ** digits - 1);
    nums.push(Math.min(1000000, Math.max(1, value)));
  }
  return [nums];
}
